\bibitem{okafor2021} N.~Okafor, P.~Silva and R.~Haas, Ceramic fillers for thermally conductive polymers, \emph{Example Polym.\ Rev.}\ \textbf{8}, 101--128 (2021).
\bibitem{tanaka2023} H.~Tanaka and E.~Moreau, Interfacial resistance in epoxy composites, \emph{Proc.\ Example Conf.\ Heat Transf.}, pp.~77--84 (2023).
\end{thebibliography}
\end{document}

