\@ifundefined{keyword}{\newenvironment{keyword}{\par\medskip\noindent\textbf{Keywords:}\ \def\sep{\unskip, }}{\par\medskip}}{}%
\@ifundefined{abstract}{\newenvironment{abstract}{\par\begin{quote}\small\noindent\textbf{Abstract.}\ }{\end{quote}\par}}{}%
\@ifundefined{table}{\newenvironment{table}[1][]{\par\begin{center}\def\caption##1{\par\textit{##1}\par}}{\end{center}\par}}{}%
\@ifundefined{caption}{\newcommand{\caption}[2][]{\par{\centering #2\par}}}{}%
}
